package io.psyllabus.platform.academic.entities;

import io.psyllabus.platform.common.audit.Auditable;
import jakarta.persistence.*;
import lombok.*;
import java.time.LocalDate;
import java.util.UUID;

/**
 * A single term within an {@link AcademicYear}.
 *
 * <p>Auto-generated by {@code AcademicTermServiceImpl.autoGenerateTerms()} using the
 * school's {@code CurriculumType}:</p>
 * <ul>
 * <li>CBC → 3 terms (Jan–Apr, May–Aug, Sep–Dec)</li>
 * <li>IGCSE → 2 terms (Sep–Dec, Jan–Jun)</li>
 * </ul>
 *
 * <p>Admins can override the exact start/end dates after auto-generation.
 * The curriculum type provides a sensible starting point, not a hard constraint.</p>
 *
 * <p>Same optimistic locking pattern as {@link AcademicYear} — prevents two concurrent
 * requests from setting two different terms as current.</p>
 */
@Entity
@Table(name = "academic_terms", indexes = {
    @Index(name = "idx_academic_term_tenant", columnList = "tenant_id"),
    @Index(name = "idx_academic_term_year", columnList = "academic_year_id"),
    @Index(name = "idx_academic_term_current", columnList = "tenant_id,is_current")
})
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class AcademicTerm extends Auditable {

    @Id
    @GeneratedValue(strategy = GenerationType.UUID)
    private UUID id;

    @Column(name = "tenant_id", nullable = false)
    private UUID tenantId;

    @Column(name = "academic_year_id", nullable = false)
    private UUID academicYearId;

    /** Display name. e.g. {@code "Term 1"}, {@code "Autumn Term"}. */
    @Column(name = "name", nullable = false, length = 50)
    private String name;

    /** Sequence within the year: 1, 2, or 3. */
    @Column(name = "term_number", nullable = false)
    private int termNumber;

    @Column(name = "start_date", nullable = false)
    private LocalDate startDate;

    @Column(name = "end_date", nullable = false)
    private LocalDate endDate;

    @Column(name = "is_current", nullable = false)
    @Builder.Default
    private boolean isCurrent = false;

    /** Optimistic lock — same pattern as {@link AcademicYear#version}. */
    @Version
    @Column(name = "version")
    private Long version;
}
